import test from 'node:test';import assert from 'node:assert/strict';import{readFileSync}from'node:fs';
import{DURATION,PHASES,validateSource,stateAt}from'./model.mjs';
const data=JSON.parse(readFileSync(new URL('assets/source-data.json',import.meta.url)));
test('source and illustrative weights cannot silently become measurements',()=>{assert.equal(validateSource(data),data);assert.throws(()=>validateSource({...data,reportedTraitValue:12}));assert.throws(()=>validateSource({...data,modelInferenceRun:true}));assert.throws(()=>validateSource({...data,results:{...data.results,aboveThreshold:31}}));});
test('every frame is reversible and map windows remain within the documented source panel',()=>{const states=Array.from({length:DURATION*24+1},(_,i)=>stateAt(i/24,data));for(let i=states.length-1;i>=0;i--){const s=stateAt(i/24,data);assert.deepEqual(s,states[i]);assert.equal(s.reportedTraitValue,null);assert(Math.abs(s.exampleWeightA+s.exampleWeightB-1)<1e-10);const [x,y,w,h]=s.mapCamera;assert(x>=1301&&x+w<=1608.001&&y>=1436&&y+h<=2781.001);assert(s.leafCamera.every(Number.isFinite));}});
test('phase boundaries and reduced motion preserve each explanation',()=>{PHASES.forEach((p,i)=>assert.equal(stateAt(p.start,data).phase,i));assert.equal(stateAt(32,data,{reducedMotion:true}).citizenOpacity,1);assert.equal(stateAt(80,data,{reducedMotion:true}).resultReveal,1);assert.equal(stateAt(200,data).time,96);});
